#!/usr/bin/env node
// Assembles database/sql/034_downstream_organizational_value_chains.sql from:
//   034_template.sql    hand-written schema, guard, backfill steps and postconditions
//   views-new.sql       v_player_control_intervals, v_transaction_asset_lineage, v_transaction_package_lineage, v_downstream_organizational_realization
//   views-amend.sql     additive amendments of the portfolio and research-queue views (generated by derive/amend_views.py)
//   exit-seed.json      the reviewed exit events, assets, identities, resolutions and asset observations (derive/assemble.py)
//   timing-seed.json    the sourced chronology facts
//   war-seed.json       Baseball-Reference team-season rows of the newly surfaced downstream PLAYER assets (derive-seed.mjs)
//   scope-config.json   data-file checksums and team-code map additions
//   audit-report.json   written by audit.mjs; the build refuses to run if the audit failed
//
//   node database/research/034/audit.mjs && node database/research/034/build.mjs
//
// Deterministic: the same inputs always produce the same file.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const read = (f) => JSON.parse(fs.readFileSync(path.join(here, f), 'utf8'))
const seed = read('exit-seed.json')
const timing = read('timing-seed.json')
const war = read('war-seed.json')
const config = read('scope-config.json')
const audit = read('audit-report.json')
if (audit.failures.length) throw new Error(`audit has failures: ${audit.failures.join('; ')}`)
if (war.coverage.persons_without_rows.length || war.coverage.unmapped_team_codes.length) throw new Error('the WAR seed has uncovered persons or unmapped team codes')

// ---- validation (fail loudly, never guess) ----------------------------------------------------------------------------
const ASSET_TYPES = ['PLAYER', 'CASH', 'PLAYER_TO_BE_NAMED', 'FUTURE_CONSIDERATIONS', 'INTERNATIONAL_BONUS_POOL_SPACE']
const EVENT_TYPES = ['TRADE', 'RELEASE', 'WAIVER', 'SALE', 'FREE_AGENCY', 'FREE_AGENT_SIGNING']
const FACT_TYPES = ['FIRST_DODGERS_APPEARANCE', 'LAST_DODGERS_APPEARANCE', 'SEASON_START_CONFIRMS_POST_ACQUISITION', 'EXIT_BOUNDED_BEFORE']
const keys = new Set()
for (const e of seed.events) {
  if (keys.has(e.key)) throw new Error(`duplicate event key ${e.key}`)
  keys.add(e.key)
  if (!EVENT_TYPES.includes(e.type)) throw new Error(`${e.key}: bad type ${e.type}`)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(e.date)) throw new Error(`${e.key}: bad date`)
  if (!e.source_url) throw new Error(`${e.key}: no source`)
  const names = new Set()
  for (const a of e.assets) {
    if (!ASSET_TYPES.includes(a.type)) throw new Error(`${e.key}: bad asset type ${a.type}`)
    const k = `${a.side}|${a.name}`
    if (names.has(k)) throw new Error(`${e.key}: duplicate asset ${k}`)
    names.add(k)
    if (a.type !== 'PLAYER' && (a.mlb_id || a.bref_id || a.bref_register_id)) throw new Error(`${e.key}: non-player asset ${a.name} carries a player identity`)
    if (a.type === 'PLAYER' && !(a.mlb_id || a.bref_id || a.bref_register_id)) throw new Error(`${e.key}: PLAYER asset ${a.name} has no stable identity`)
    if (a.bref_id && !/^[a-z0-9]+$/.test(a.bref_id)) throw new Error(`${e.key}: bad bref_id ${a.bref_id}`)
    if (a.bref_register_id && !/^[a-z][a-z-]{2,5}[0-9]{3}[a-z]{1,4}$/.test(a.bref_register_id)) throw new Error(`${e.key}: bad register id ${a.bref_register_id}`)
    if (a.mlb_id && !/^[0-9]+$/.test(a.mlb_id)) throw new Error(`${e.key}: bad mlb_id ${a.mlb_id}`)
  }
  if (e.type === 'TRADE') {
    for (const a of e.assets) if (!a.counterparty) throw new Error(`${e.key}: trade asset ${a.name} has no counterparty`)
  }
}
for (const t of timing.facts) {
  if (!FACT_TYPES.includes(t.fact_type)) throw new Error(`bad timing fact type ${t.fact_type}`)
  if ((t.fact_type === 'EXIT_BOUNDED_BEFORE') !== (t.season === null)) throw new Error(`timing fact ${t.fact_type} season rule violated`)
  if (t.season !== null && Number(t.observed_date.slice(0, 4)) !== t.season) throw new Error(`timing fact ${t.asset.name}: season does not match the date`)
}

// ---- sources ----------------------------------------------------------------------------------------------------------
const urls = new Set()
for (const e of seed.events) urls.add(e.source_url)
for (const r of seed.resolutions) urls.add(r.source_url)
for (const o of seed.asset_observations) urls.add(o.source_url)
for (const t of timing.facts) urls.add(t.source_url)
const TEAMS = { BRO: 'Brooklyn Dodgers', LAD: 'Los Angeles Dodgers' }
const describe = (u) => {
  let m = u.match(/baseball-reference\.com\/teams\/(BRO|LAD)\/(\d{4})-transactions\.shtml$/)
  if (m) return { source_name: 'Baseball-Reference', source_type: 'TRANSACTIONS', source_tier: 'BASEBALL_REFERENCE', title: `${m[2]} ${TEAMS[m[1]]} team transactions` }
  m = u.match(/baseball-reference\.com\/teams\/(BRO|LAD)\/(\d{4})-schedule-scores\.shtml$/)
  if (m) return { source_name: 'Baseball-Reference', source_type: 'TEAM_SCHEDULE', source_tier: 'BASEBALL_REFERENCE', title: `${m[2]} ${TEAMS[m[1]]} schedule and results` }
  m = u.match(/statsapi\.mlb\.com\/api\/v1\/transactions\?playerId=(\d+)$/)
  if (m) return { source_name: 'MLB Stats API', source_type: 'MLB_PLAYER_TRANSACTIONS', source_tier: 'MLB_TRANSACTION_LOG', title: `MLB transaction log: player ${m[1]}` }
  m = u.match(/statsapi\.mlb\.com\/api\/v1\/people\/(\d+)\/stats\?stats=gameLog&season=(\d{4})&group=(\w+)$/)
  if (m) return { source_name: 'MLB Stats API', source_type: 'MLB_GAME_LOG', source_tier: 'MILB_MLB_PLAYER_RECORD', title: `MLB ${m[2]} game log (${m[3]}): player ${m[1]}` }
  throw new Error(`no source description for ${u}`)
}
const sources = [...urls].sort().map((u) => ({ url: u, ...describe(u), notes: null }))
const sourceUrls = new Set(sources.map((s) => s.url))
for (const r of seed.resolutions) if (!sourceUrls.has(r.source_url)) throw new Error(`resolution source ${r.source_url} unregistered`)

// ---- payload ---------------------------------------------------------------------------------------------------------
const organizations = new Set(config.team_code_map_additions.map((m) => m.organization))
for (const e of seed.events) {
  organizations.add(e.from_org)
  if (e.to_org) organizations.add(e.to_org)
  for (const a of e.assets) if (a.counterparty) organizations.add(a.counterparty)
}
const newAssets = seed.events.reduce((n, e) => n + e.assets.length, 0)
const sortKeys = (v) => (Array.isArray(v) ? v.map(sortKeys) : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, sortKeys(v[k])])) : v)
const payload = sortKeys({
  retrieved_at: '2026-10-11T00:00:00Z',
  expected_prior_events: audit.baseline.events,
  expected_total_assets: audit.baseline.assets + newAssets,
  organizations: [...organizations].sort(),
  sources,
  team_map: config.team_code_map_additions.map((m) => ({ code: m.code, organization: m.organization, from: m.from, to: m.to, note: m.note })),
  events: seed.events.map((e) => ({
    key: e.key, date: e.date, type: e.type, label: e.historical_label, multi: e.is_multi_team, from: e.from_org, to: e.to_org,
    description: e.description, source_url: e.source_url,
    assets: e.assets.map((a) => ({ side: a.side, type: a.type, name: a.name, mlb_id: a.mlb_id, bref_id: a.bref_id, register_id: a.bref_register_id,
      cp: a.counterparty, cash: a.cash_amount_usd, pool: a.pool_space_amount_usd, note: a.role_note })),
  })),
  resolutions: seed.resolutions.map((r) => ({ event: r.event, placeholder: r.placeholder, resolved: r.resolved, date: r.date, source_url: r.source_url, confidence: r.confidence, note: r.note })),
  asset_observations: seed.asset_observations.map((o) => ({ asset: o.asset, type: o.type, observed_through: o.observed_through, confidence: o.confidence, source_url: o.source_url, note: o.note })),
  timing: timing.facts.map((t) => ({ asset: t.asset, fact_type: t.fact_type, season: t.season, observed_date: t.observed_date, source_url: t.source_url, confidence: t.confidence, note: t.note })),
  war: {
    bat_url: config.files.bat.url,
    pitch_url: config.files.pitch.url,
    source_urls: [config.files.bat.url, config.files.pitch.url],
    retrieved_at: config.retrieved_at,
    observed_through_date: config.file_last_modified,
    observed_through_season: Number(config.file_last_modified.slice(0, 4)),
    rows: war.rows.map((r) => [r.bref_id, r.mlb_id, r.season, r.team, r.stint, r.component, r.league, r.war, r.games, r.pa, r.ip_outs]),
  },
})
const json = JSON.stringify(payload).replace(/[\u007f-￿]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'))
if (json.includes('$m034$')) throw new Error('payload contains the dollar-quote tag')

let sql = fs.readFileSync(path.join(here, '034_template.sql'), 'utf8').replace(/\r\n/g, '\n')
const views = ['views-new.sql', 'views-amend.sql'].map((f) => fs.readFileSync(path.join(here, f), 'utf8').replace(/\r\n/g, '\n').trimEnd()).join('\n\n')
const fill = (name, value) => {
  const token = `{{${name}}}`
  if (!sql.includes(token)) throw new Error(`template has no ${token}`)
  sql = sql.split(token).join(value)
}
fill('views', views)
fill('payload_json', json)
if (/\{\{\w+\}\}/.test(sql)) throw new Error('unreplaced placeholder')

const dest = path.join(here, '../../sql/034_downstream_organizational_value_chains.sql')
fs.writeFileSync(dest, sql)
process.stderr.write(`wrote ${path.relative(process.cwd(), dest)} (${sql.split('\n').length - 1} lines)\n`)
